import{g as a,ae as e,r as n,B as t}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"useList","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/use-list.md","filePath":"docs/data-fetching/use-list.md","lastUpdated":1790275646000}'),p={name:"docs/data-fetching/use-list.md"};function c(d,s,o,l,r,i){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="uselist" tabindex="-1">useList <a class="header-anchor" href="#uselist" aria-label="Permalink to “useList”">​</a></h1><p><code>useList</code> fetches a page of documents of a DocType, with filters, sorting, paging and write members. Its rows stay in sync with <a href="./use-doc"><code>useDoc</code></a>.</p><h2 id="basic-example" tabindex="-1">Basic example <a class="header-anchor" href="#basic-example" aria-label="Permalink to “Basic example”">​</a></h2><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> v-for</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo in todos.data</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.name</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ todo.description }} ({{ todo.status }})</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todos.hasNextPage</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todos.next()</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Load more</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useList</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todos</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useList</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  fields</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">description</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">status</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  orderBy</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">creation desc</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  limit</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> 20</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>next()</code> fetches the next page and adds its rows to the end of <code>data</code>.</p><h2 id="filter-the-list" tabindex="-1">Filter the list <a class="header-anchor" href="#filter-the-list" aria-label="Permalink to “Filter the list”">​</a></h2><p>Give each field a value to match, or an <code>[operator, value]</code> pair. When a ref or getter in <code>filters</code> changes, the list fetches again:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useList</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> status</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Open</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todos</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useList</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  filters</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">    status</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    priority</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">in</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">High</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Urgent</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    description</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">like</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">deploy</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>A <code>like</code> value without <code>%</code> is wrapped in <code>%</code> on both sides, and an empty <code>like</code> value is left out.</p><h2 id="update-a-row" tabindex="-1">Update a row <a class="header-anchor" href="#update-a-row" aria-label="Permalink to “Update a row”">​</a></h2><p><code>setValue.isLoading(name)</code> shows a loading state on one row while it saves:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useList</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todos</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useList</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> fields</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">description</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> })</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">async</span><span class="s_50ecpt"> function</span><span class="s_indoxt"> close</span><span class="s_13ahmt">(</span><span class="s_fsg3al">name</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_22m8k2">name</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Closed</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> v-for</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo in todos.data</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todo.name</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">    {{ todo.description }}</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_1uuh8p">Button</span></span>
<span class="line"><span class="s_1i4ay4">      :loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todos.setValue.isLoading(todo.name)</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1i4ay4">      @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">close(todo.name)</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1zd9e2">    &gt;</span></span>
<span class="line"><span class="s_6am9cx">      Close</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Each submit sends its own request, so two rows can save or delete at the same time.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>doctype</code></td><td><code>string</code></td><td>required</td><td>The DocType to list.</td></tr><tr><td><code>fields</code></td><td><code>Array</code></td><td>server default</td><td>Fields per row: <code>&#39;name&#39;</code>, <code>&#39;*&#39;</code>, <code>&#39;field as alias&#39;</code>, <code>&#39;link_field.fieldname&#39;</code>, or a child table such as <code>{ items: [&#39;item_code&#39;, &#39;qty&#39;] }</code>.</td></tr><tr><td><code>filters</code></td><td><code>MaybeRefOrGetter&lt;Filters&gt;</code></td><td></td><td>Field names mapped to a value to match or an <code>[operator, value]</code> pair. Values can be refs or getters.</td></tr><tr><td><code>orderBy</code></td><td><code>MaybeRefOrGetter&lt;OrderBy&gt;</code></td><td></td><td><code>&#39;&lt;field&gt; asc&#39;</code> or <code>&#39;&lt;field&gt; desc&#39;</code>.</td></tr><tr><td><code>start</code></td><td><code>number</code></td><td><code>0</code></td><td>The offset of the first row.</td></tr><tr><td><code>limit</code></td><td><code>number</code></td><td><code>20</code></td><td>The page size.</td></tr><tr><td><code>groupBy</code></td><td><code>string</code></td><td></td><td>A field to group rows by.</td></tr><tr><td><code>parent</code></td><td><code>string</code></td><td></td><td>For a child table DocType, the parent DocType.</td></tr><tr><td><code>debug</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Asks the server for debug output and logs it to the console.</td></tr><tr><td><code>immediate</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Fetches the first page when <code>useList</code> runs.</td></tr><tr><td><code>refetch</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Fetches again when <code>filters</code> or <code>orderBy</code> change, and after each successful write.</td></tr><tr><td><code>initialData</code></td><td><code>T[]</code></td><td></td><td>The rows to show before the first response, in the shape the server sends. They go through <code>transform</code>, the same as a response.</td></tr><tr><td><code>cacheKey</code></td><td><code>CacheKey</code></td><td></td><td>A string or an array. Saves the rows in IndexedDB and shows them at once on the next <code>useList</code> with this key. Each user has their own saved rows: see <a href="./use-call#cache-namespace">One cache per user</a>.</td></tr><tr><td><code>staleOnError</code></td><td><code>boolean</code></td><td><code>false</code></td><td>With <code>cacheKey</code>, a failed fetch keeps showing the cached rows. A Frappe error response still clears them.</td></tr><tr><td><code>transform</code></td><td><code>(rows: T[]) =&gt; T[]</code></td><td></td><td>Changes the rows before they go into <code>data</code>. It gets every row loaded so far, from all pages, and runs again after each new page or row change. It gets a copy, so it may change the rows in place.</td></tr><tr><td><code>onSuccess</code></td><td><code>(rows: T[]) =&gt; void</code></td><td></td><td>Called with all loaded rows after each successful fetch.</td></tr><tr><td><code>onError</code></td><td><code>(error: Error) =&gt; void</code></td><td></td><td>Called with the error after each failed fetch.</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td><code>/api/v2/document/&lt;doctype&gt;</code></td><td>Replaces the URL of the fetch. The list params are still added.</td></tr><tr><td><code>baseUrl</code></td><td><code>string</code></td><td><code>&#39;&#39;</code></td><td>A prefix for every request URL.</td></tr></tbody></table><h2 id="return-value" tabindex="-1">Return value <a class="header-anchor" href="#return-value" aria-label="Permalink to “Return value”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>data</code></td><td><code>T[] | null</code></td><td>The rows loaded so far, or <code>null</code> before the first response.</td></tr><tr><td><code>error</code></td><td><code>Error | null</code></td><td>The error from the last fetch.</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td><code>true</code> while a fetch is in flight. Also available as <code>isFetching</code>.</td></tr><tr><td><code>isFinished</code></td><td><code>boolean</code></td><td><code>true</code> once the current fetch has settled, with or without an error.</td></tr><tr><td><code>hasNextPage</code></td><td><code>boolean</code></td><td><code>true</code> if the server has more rows after the last page.</td></tr><tr><td><code>hasPreviousPage</code></td><td><code>boolean</code></td><td><code>true</code> if <code>start</code> is above <code>0</code>.</td></tr><tr><td><code>start</code></td><td><code>number</code></td><td>The offset of the current page.</td></tr><tr><td><code>limit</code></td><td><code>number</code></td><td>The page size.</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>The full request URL.</td></tr><tr><td><code>canAbort</code></td><td><code>boolean</code></td><td><code>true</code> while a fetch that can be aborted is in flight.</td></tr><tr><td><code>aborted</code></td><td><code>boolean</code></td><td><code>true</code> if the last fetch was aborted.</td></tr><tr><td><code>reload()</code></td><td><code>() =&gt; Promise</code></td><td>Fetches again from <code>start</code>. Resolves even if it fails, so check <code>error</code>. Also available as <code>execute()</code> and <code>fetch()</code>.</td></tr><tr><td><code>abort()</code></td><td><code>() =&gt; void</code></td><td>Aborts the fetch in flight.</td></tr><tr><td><code>next()</code></td><td><code>() =&gt; void</code></td><td>Moves <code>start</code> forward one page and fetches it.</td></tr><tr><td><code>previous()</code></td><td><code>() =&gt; void</code></td><td>Moves <code>start</code> back one page and fetches it.</td></tr><tr><td><code>updateRow(doc)</code></td><td><code>(doc) =&gt; void</code></td><td>Changes the row with the same <code>name</code> in <code>data</code>, without a request. Only fields the row has change. Pass values as the server sends them: <code>transform</code> runs again on the row.</td></tr><tr><td><code>removeRow(name)</code></td><td><code>(name: string) =&gt; void</code></td><td>Removes the row with this <code>name</code> from <code>data</code>, without a request.</td></tr><tr><td><code>insert</code></td><td>write member</td><td><code>insert.submit(values)</code> creates a document. <code>insert.isLoading()</code> takes no argument.</td></tr><tr><td><code>setValue</code></td><td>write member</td><td><code>setValue.submit({ name, ...values })</code> saves fields of one document. <code>setValue.isLoading(name)</code> checks one row.</td></tr><tr><td><code>delete</code></td><td>write member</td><td><code>delete.submit({ name })</code> deletes one document. <code>delete.isLoading(name)</code> checks one row.</td></tr></tbody></table><p>A write member has <code>data</code>, <code>error</code>, <code>loading</code>, <code>submit(params)</code> and <code>isLoading(...)</code>. <code>loading</code> is <code>true</code> while any submit of that member is in flight. <code>data</code> and <code>error</code> belong to the submit that started last. With <code>refetch: true</code>, a successful write fetches the list again.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p><code>insert</code>, <code>setValue</code> and <code>delete</code> reject when they fail, so catch the error. <code>reload()</code> resolves and sets <code>error</code>. See <a href="./use-call#errors">Errors</a> for the rule and the error classes.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">delete</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_22m8k2">name</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">message</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h2 id="shared-cache" tabindex="-1">Shared cache <a class="header-anchor" href="#shared-cache" aria-label="Permalink to “Shared cache”">​</a></h2><p>Rows of a <code>useList</code> and documents of a <a href="./use-doc"><code>useDoc</code></a> with the same <code>doctype</code> and <code>name</code> stay in sync. A save or delete through one updates the other, and every other <code>useList</code> of that DocType.</p>`,23)])])}const u=a(p,[["render",c]]);export{_ as __pageData,u as default};
